<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/app/helpers/industry-classes.php';
$user=require_role('admin','staf_bkk');$ready=industry_ready();$q=input_text($_GET,'q');$status=input_text($_GET,'status');
if(!valid_text($q,100,false)||!in_array($status,['','aktif','arsip'],true)){http_response_code(400);exit('Filter kelas tidak valid.');}
$where='1=1';$params=[];
if($q!==''){$pattern='%'.str_replace(['!','%','_'],['!!','!%','!_'],$q).'%';$where.=" AND (c.nama LIKE :nama ESCAPE '!' OR m.nama LIKE :mitra ESCAPE '!' OR c.kelas_sasaran LIKE :sasaran ESCAPE '!')";$params=['nama'=>$pattern,'mitra'=>$pattern,'sasaran'=>$pattern];}
if($status!==''){$where.=' AND c.status=:status';$params['status']=$status;}
$from=' FROM industry_classes c JOIN mitra m ON m.id=c.mitra_id WHERE '.$where;
$total=$ready?(int)panel_query('SELECT COUNT(*)'.$from,$params)->fetchColumn():0;$pages=max(1,(int)ceil($total/20));$page=min($pages,positive_id($_GET['page']??'1')??1);
$rows=$ready?panel_query("SELECT c.*,m.nama AS mitra_nama,(SELECT COUNT(*) FROM industry_class_meetings a WHERE a.class_id=c.id AND a.status='terlaksana') AS terlaksana".$from.' ORDER BY c.updated_at DESC,c.id DESC LIMIT :limit OFFSET :offset',$params+['limit'=>20,'offset'=>($page-1)*20])->fetchAll():[];
panel_start($user,'Kelas Industri','kelas-industri');
?>
<div class="industry-list-workspace">
<div class="page-actions industry-list-header"><div><h1><?= panel_icon('program') ?> Kelas Industri</h1></div><div class="industry-header-actions"><a class="button industry-add" href="<?= e(base_url('panel/kelas-industri/form.php')) ?>"><?= panel_icon('add') ?> Tambah kelas</a><?php if(user_can($user,'program')): ?><a class="button industry-description" href="<?= e(base_url('panel/program/deskripsi.php')) ?>"><?= panel_icon('capaian') ?> Deskripsi BMW Sakti</a><?php endif; ?></div></div>
<?php if(!$ready): ?><p class="notice">Modul belum aktif. Impor database/updates/021_industry_classes.sql.</p><?php endif; ?>
<form class="filter-form card industry-list-filter" method="get"><label for="industry-search"><span><?= panel_icon('search') ?> Cari kelas</span><input id="industry-search" placeholder="Nama kelas, mitra, atau sasaran" name="q" maxlength="100" value="<?= e($q) ?>"></label><label for="industry-status"><span><?= panel_icon('check-circle') ?> Status kelas</span><select id="industry-status" name="status"><?php foreach([''=>'Semua','aktif'=>'Aktif','arsip'=>'Arsip'] as $key=>$label): ?><option value="<?= $key ?>" <?= $status===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><button type="submit"><?= panel_icon('search') ?> Cari</button><a href="<?= e(base_url('panel/kelas-industri/')) ?>"><?= panel_icon('reset') ?> Reset</a></form>
<div class="industry-list-caption"><h2><?= panel_icon('identity') ?> Daftar kelas</h2><p><?= $total ?> kelas · Halaman <?= $page ?> dari <?= $pages ?></p></div><div class="table-scroll panel-sheet industry-class-sheet" data-vertical-list tabindex="0" role="region" aria-label="Daftar kelas industri, gulir untuk melihat kolom lainnya"><table><thead><tr><th><span><?= panel_icon('program') ?> Nama kelas</span></th><th><span><?= panel_icon('mitra') ?> Mitra</span></th><th><span><?= panel_icon('peserta') ?> Sasaran</span></th><th><span><?= panel_icon('tracer') ?> Progres pertemuan</span></th><th><span><?= panel_icon('check-circle') ?> Status</span></th><th><span><?= panel_icon('pengaturan') ?> Tindakan</span></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><strong><?= e($row['nama']) ?></strong></td><td><?= e($row['mitra_nama']) ?></td><td><?= e($row['kelas_sasaran']?:'Peserta terdaftar pada kelas') ?></td><td><div class="industry-meeting-progress"><span><strong><?= (int)$row['terlaksana'] ?> / <?= (int)$row['rencana_pertemuan'] ?></strong> terlaksana</span><progress value="<?= (int)$row['terlaksana'] ?>" max="<?= (int)$row['rencana_pertemuan'] ?>" aria-label="<?= e('Pertemuan '.$row['nama'].': '.(int)$row['terlaksana'].' dari '.(int)$row['rencana_pertemuan'].' terlaksana') ?>"></progress></div></td><td><span class="industry-status-badge <?= $row['status']==='aktif'?'is-active':'is-archived' ?>"><?= panel_icon($row['status']==='aktif'?'check-circle':'capaian') ?> <?= e(ucfirst($row['status'])) ?></span></td><td><div class="industry-row-actions"><a class="industry-schedule" href="<?= e(base_url('panel/kelas-industri/detail.php?id='.$row['id'])) ?>"><?= panel_icon('calendar') ?> Jadwal</a><a class="industry-edit" href="<?= e(base_url('panel/kelas-industri/form.php?id='.$row['id'])) ?>"><?= panel_icon('edit') ?> Edit</a></div></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6"><?= $q!==''||$status!==''?'Tidak ada kelas sesuai filter. Gunakan Reset untuk melihat semua kelas.':'Belum ada kelas industri. Gunakan Tambah kelas untuk memulai.' ?></td></tr><?php endif; ?></tbody></table></div>
<nav class="pagination" aria-label="Halaman kelas industri"><?php foreach(['Sebelumnya'=>$page-1,'Berikutnya'=>$page+1] as $label=>$target):if($target<1||$target>$pages){continue;} ?><a href="<?= e(base_url('panel/kelas-industri/?'.http_build_query(['q'=>$q,'status'=>$status,'page'=>$target]))) ?>"><?= $label ?></a><?php endforeach; ?></nav>
</div>
<?php panel_end($user); ?>
